import{_ as t,o,c as i,a2 as d}from"./chunks/framework.BUwdTBzS.js";const p=JSON.parse('{"title":"micro-fix 轻量保留版执行规范（v2）","description":"","frontmatter":{"title":"micro-fix 轻量保留版执行规范（v2）"},"headers":[],"relativePath":"dev-flow/references/micro-fix-light.md","filePath":"dev-flow/references/micro-fix-light.md","lastUpdated":null}'),a={name:"dev-flow/references/micro-fix-light.md"};function l(r,e,c,s,n,h){return o(),i("div",null,[...e[0]||(e[0]=[d(`<blockquote><p>📄 本页由源文件 <code>skills/dev-flow/references/micro-fix-light.md</code> 自动投影生成（单一权威源）。请勿直接编辑本页。</p></blockquote><h1 id="micro-fix-轻量保留版执行规范-v2" tabindex="-1">micro-fix 轻量保留版执行规范（v2） <a class="header-anchor" href="#micro-fix-轻量保留版执行规范-v2" aria-label="Permalink to &quot;micro-fix 轻量保留版执行规范（v2）&quot;">​</a></h1><blockquote><p>本文件定义 micro-fix 模式下「轻量保留」的 5 个环节执行边界、成本上限与自动降级触发条件。 由 <code>step-7-commit.md</code> 在 <code>caller=micro-fix-7</code> 时按需引用，<code>mode-matrix.md</code> §三bis 引用本文件作为执行细则单一真相源。 设计哲学：从「极致裁剪」转向「零成本保留 + 极简版执行」——保留所有有价值的环节，但每个环节执行最小集；降级机制不变，确保超出阈值时回到完整流程。</p></blockquote><hr><h2 id="一、轻量保留的-5-个环节总览" tabindex="-1">一、轻量保留的 5 个环节总览 <a class="header-anchor" href="#一、轻量保留的-5-个环节总览" aria-label="Permalink to &quot;一、轻量保留的 5 个环节总览&quot;">​</a></h2><p>&lt;!-- markdownlint-disable MD013 --&gt;</p><table tabindex="0"><thead><tr><th>#</th><th>环节</th><th>极简版动作</th><th>成本上限</th><th>触发自动降级条件</th></tr></thead><tbody><tr><td>1</td><td>5.5a L1 极简审查</td><td>仅扫改动行 + 红线 §5/6/7/9 共 4 项</td><td>1 次 use_skill</td><td>发现 ≥3 个 🔴 / 需决策性思考的 🔴</td></tr><tr><td>2</td><td>7-A Diff 极简分析</td><td><code>git diff HEAD --stat</code> 统计 + 文件类型识别</td><td>1 次 bash</td><td>改动 &gt;3 文件 / &gt;15 行（单文件）/ 不对称修改 / 涉及 lock 或配置文件</td></tr><tr><td>3</td><td>7-H.2 devlog 极简追加</td><td>当前 Round 末尾追加 1 行</td><td>1 次 read_file + 1 次 replace_in_file</td><td>—</td></tr><tr><td>4</td><td>7-H.3 knowledge 漂移检测</td><td>grep 反查 + 命中模块变更历史追加</td><td>0~1 次 use_skill</td><td>knowledge 描述与改动冲突 → 仅追加变更历史，不降级</td></tr><tr><td>5</td><td>7-J 经验快检（Q1+Q2）</td><td>仅 Q1 用户纠正 + Q2 踩坑递增，跳 Q3</td><td>静默 ≤15 秒</td><td>—</td></tr><tr><td>&lt;!-- markdownlint-enable MD013 --&gt;</td><td></td><td></td><td></td><td></td></tr></tbody></table><blockquote><p>跳过的 2 个环节（仍保持当前 micro-fix 设计）：</p><ul><li><strong>7-C 可选链 + 7-E TODO 检查</strong>：L1 极简审查的红线 §7 已覆盖可选链；TODO 在字面修复中无意义</li><li><strong>7-I 数据驱动反思</strong>：micro-fix 不采集 metrics，反思缺数据基础（强行反思反而是噪声）</li></ul></blockquote><h2 id="二、5-5a-l1-极简审查" tabindex="-1">二、5.5a L1 极简审查 <a class="header-anchor" href="#二、5-5a-l1-极简审查" aria-label="Permalink to &quot;二、5.5a L1 极简审查&quot;">​</a></h2><blockquote><p>在 micro-fix 模式下，5.5a 从 ❌ 跳过 → ⚡ 极简版执行。</p></blockquote><h3 id="_2-1-执行边界" tabindex="-1">2.1 执行边界 <a class="header-anchor" href="#_2-1-执行边界" aria-label="Permalink to &quot;2.1 执行边界&quot;">​</a></h3><ul><li><strong>调用方式</strong>：<code>use_skill(&#39;code-review&#39;)</code> 执行 <strong>L1 基础审查</strong> （code-review skill 仅有 L1/L2/L3 三个实际级别，本环节限定为 L1）</li><li><strong>扫描范围</strong>：本次 diff 的改动行（不扫全文件，不扫上下文 ±N 行）</li><li><strong>检查清单裁剪</strong>：只汇报「开发规范-红线」 §5/6/7/9 命中项，其他项静默跳过：</li><li>§5 安全底线（SQL/HTML 拼接、硬编码密钥）</li><li>§6 副作用清理（useEffect cleanup / 卸载后 setState）</li><li>§7 边界条件 + 可选链 <code>?.</code></li><li>§9 错误处理（空 catch / Error Boundary）</li><li><strong>其余 L1 项静默</strong>：§1/2/3/4/8 不作为本环节的 🔴 拦截项（这些不是 1 行修改能引入的问题）</li></ul><blockquote><p>💡 <strong>实现备注</strong>：code-review skill 本身不提供 <code>mode=micro-fix-light</code> 入参， 本环节通过「调用 L1 + AI 在 prompt 中明示扫描范围与检查清单」实现轻量化。</p></blockquote><h3 id="_2-2-严重度处理" tabindex="-1">2.2 严重度处理 <a class="header-anchor" href="#_2-2-严重度处理" aria-label="Permalink to &quot;2.2 严重度处理&quot;">​</a></h3><table tabindex="0"><thead><tr><th>严重度</th><th>处理</th><th>是否弹 ask_followup_question</th></tr></thead><tbody><tr><td>🔴 必须修复</td><td>立即修复并重新 lint</td><td>不弹（修复后静默推进）</td></tr><tr><td>🟡 建议项</td><td>静默跳过</td><td>不弹（不打扰 micro-fix 节奏）</td></tr><tr><td>🟢 提示</td><td>忽略</td><td>不弹</td></tr></tbody></table><h3 id="_2-3-自动降级触发" tabindex="-1">2.3 自动降级触发 <a class="header-anchor" href="#_2-3-自动降级触发" aria-label="Permalink to &quot;2.3 自动降级触发&quot;">​</a></h3><p>满足任一即触发自动降级到 standard：</p><ul><li>发现 ≥3 个 🔴</li><li>发现需要决策性思考的 🔴（如架构选择、业务语义重定义）</li></ul><h3 id="_2-4-完成标记" tabindex="-1">2.4 完成标记 <a class="header-anchor" href="#_2-4-完成标记" aria-label="Permalink to &quot;2.4 完成标记&quot;">​</a></h3><ul><li>L1 通过 → 5.5 完成标记 <code>l1_review_result: &quot;passed_micro_light&quot;</code></li><li>L1 修复 N 个 🔴 → <code>l1_review_result: &quot;fixed_N_issues_micro_light&quot;</code></li></ul><h2 id="三、7-a-diff-极简分析" tabindex="-1">三、7-A Diff 极简分析 <a class="header-anchor" href="#三、7-a-diff-极简分析" aria-label="Permalink to &quot;三、7-A Diff 极简分析&quot;">​</a></h2><blockquote><p>在 micro-fix 模式下，7-A 从 ❌ 跳过 → ⚡ 极简版执行。</p></blockquote><h3 id="_3-1-执行边界" tabindex="-1">3.1 执行边界 <a class="header-anchor" href="#_3-1-执行边界" aria-label="Permalink to &quot;3.1 执行边界&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diff</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> HEAD</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --stat</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 一条命令统计所有本地未提交改动（含 unstaged + staged），自动去重</span></span></code></pre></div><blockquote><p>micro-fix 场景检查的是<strong>当前未提交的本地改动</strong> （非功能分支 vs 主干的全量差异）。 使用 <code>git diff HEAD --stat</code> 而非分开的 <code>git diff --stat</code> + <code>git diff --cached --stat</code>， 避免同一文件同时存在 unstaged 和 staged 改动时的 行数重复计算和文件数歧义。</p></blockquote><h3 id="_3-2-检测规则-按顺序检查-命中即处理" tabindex="-1">3.2 检测规则（按顺序检查，命中即处理） <a class="header-anchor" href="#_3-2-检测规则-按顺序检查-命中即处理" aria-label="Permalink to &quot;3.2 检测规则（按顺序检查，命中即处理）&quot;">​</a></h3><p>&lt;!-- markdownlint-disable MD013 --&gt;</p><table tabindex="0"><thead><tr><th>检测项</th><th>处理方式</th></tr></thead><tbody><tr><td>改动文件数 &gt; 1</td><td>🔴 自动降级到 standard</td></tr><tr><td>改动行数 &gt; 15</td><td>🔴 自动降级到 standard</td></tr><tr><td>出现 lock 文件（<code>*.lock</code> / <code>package-lock.json</code> / <code>yarn.lock</code> / <code>pnpm-lock.yaml</code>）</td><td>🔴 必须 ask_followup_question 用户确认</td></tr><tr><td>出现 <code>package.json</code> / <code>tsconfig.json</code> / <code>.eslintrc*</code> / <code>vite.config.*</code> / <code>webpack.config.*</code> 等配置文件</td><td>🔴 必须 ask_followup_question 用户确认</td></tr><tr><td>出现非 user_provided_fix_location 中声明的文件</td><td>🔴 必须 ask_followup_question 用户确认</td></tr><tr><td>改动文件 = 1 且 ≤15 行且非保护文件</td><td>✅ 静默通过</td></tr><tr><td>&lt;!-- markdownlint-enable MD013 --&gt;</td><td></td></tr></tbody></table><h3 id="_3-3-完成标记" tabindex="-1">3.3 完成标记 <a class="header-anchor" href="#_3-3-完成标记" aria-label="Permalink to &quot;3.3 完成标记&quot;">​</a></h3><ul><li>通过 → 在步骤 7 完成标记 outputs 中追加 <code>diff_stat_checked: true</code></li><li>触发降级 → 工作上下文 <code>mode_history</code> 追加降级记录</li></ul><h2 id="四、7-h-2-devlog-极简追加" tabindex="-1">四、7-H.2 devlog 极简追加 <a class="header-anchor" href="#四、7-h-2-devlog-极简追加" aria-label="Permalink to &quot;四、7-H.2 devlog 极简追加&quot;">​</a></h2><blockquote><p>在 micro-fix 模式下，7-H.2 从 ❌ 跳过 → ⚡ 极简版执行。 🔴 <strong>不可跳过</strong>：本环节在 H.1 commit 决策后执行，无论用户选择提交还是跳过提交，不可豁免。</p></blockquote><h3 id="_4-1-执行规则-按优先级判定" tabindex="-1">4.1 执行规则（按优先级判定） <a class="header-anchor" href="#_4-1-执行规则-按优先级判定" aria-label="Permalink to &quot;4.1 执行规则（按优先级判定）&quot;">​</a></h3><p><strong>优先级 1</strong>：找到当前活跃需求的 devlog（<code>~/.codebuddy/dev-logs/{当前 dir_name}/devlog.md</code>）</p><ul><li>在最后 Round 末尾追加 1 行：</li></ul><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">micro-fix</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] {YYYY-MM-DD HH:mm} {commit_hash[</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">:8</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]} {一句话描述}（</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`{改动文件相对路径}\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> L{行号}）</span></span></code></pre></div><p><strong>优先级 2</strong>：无活跃需求 → 写入月度合集</p><ul><li>路径：<code>~/.codebuddy/dev-logs/_micro-fixes/{YYYY-MM}.md</code></li><li>文件不存在则创建（首次写入需填写 H1 标题 <code># Micro-Fix 月度合集 - {YYYY-MM}</code>）</li><li>追加格式同上</li></ul><h3 id="_4-2-禁止行为" tabindex="-1">4.2 禁止行为 <a class="header-anchor" href="#_4-2-禁止行为" aria-label="Permalink to &quot;4.2 禁止行为&quot;">​</a></h3><ul><li>❌ 禁止主动新建独立 devlog 文件（避免 dev-logs 目录碎片化）</li><li>❌ 禁止在 micro-fix 月度合集外引入新的章节结构（仅追加单行）</li><li>❌ 禁止追加超过 1 行的内容（详细描述放到 commit message 中）</li></ul><h3 id="_4-3-完成标记" tabindex="-1">4.3 完成标记 <a class="header-anchor" href="#_4-3-完成标记" aria-label="Permalink to &quot;4.3 完成标记&quot;">​</a></h3><ul><li>在步骤 7 完成标记 outputs 中：<code>devlog_appended: &quot;round_appended&quot; | &quot;monthly_appended&quot;</code></li><li>⚠️ 注意：micro-fix 的 <code>devlog_generated</code> 字段保持 <code>false</code> （语义=未生成独立 devlog 文件）， 通过新字段 <code>devlog_appended</code> 区分「追加到现有/月度合集」</li></ul><h2 id="五、7-h-3-knowledge-漂移检测" tabindex="-1">五、7-H.3 knowledge 漂移检测 <a class="header-anchor" href="#五、7-h-3-knowledge-漂移检测" aria-label="Permalink to &quot;五、7-H.3 knowledge 漂移检测&quot;">​</a></h2><blockquote><p>在 micro-fix 模式下，7-H.3 从 ❌ 跳过 → ⚡ 极简版执行。 这是本轮改造<strong>最关键</strong>的环节，目标是防止 micro-fix 的局部修复污染 knowledge 全局认知。 🔴 <strong>不可跳过</strong>：本环节在 H.1 commit 决策后执行，无论用户选择提交还是跳过提交，不可豁免。</p></blockquote><h3 id="_5-1-执行流程-两步法-零命中即零成本" tabindex="-1">5.1 执行流程（两步法，零命中即零成本） <a class="header-anchor" href="#_5-1-执行流程-两步法-零命中即零成本" aria-label="Permalink to &quot;5.1 执行流程（两步法，零命中即零成本）&quot;">​</a></h3><h4 id="step-1-grep-反查" tabindex="-1">Step 1：grep 反查 <a class="header-anchor" href="#step-1-grep-反查" aria-label="Permalink to &quot;Step 1：grep 反查&quot;">​</a></h4><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 对每个改动文件执行</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;{改动文件相对路径}&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.codebuddy/knowledge/{project}/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/dev/null</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ||</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span></span></code></pre></div><ul><li>0 命中 → 静默退出（成本 0）</li><li>有命中 → 进入 Step 2</li></ul><h4 id="step-2-调用-knowledge-loop-skill-检索模式-进行漂移检测" tabindex="-1">Step 2：调用 knowledge-loop skill（检索模式）进行漂移检测 <a class="header-anchor" href="#step-2-调用-knowledge-loop-skill-检索模式-进行漂移检测" aria-label="Permalink to &quot;Step 2：调用 knowledge-loop skill（检索模式）进行漂移检测&quot;">​</a></h4><ul><li>调用：<code>use_skill(&#39;knowledge-loop&#39;)</code>，明示「检索模式」并请求运行漂移检测 （<code>references/confidence.md</code> §「代码漂移检测」内置能力， 根据 <code>stability.last_verified</code> / <code>drift_count</code> 字段判定）</li><li>输入：命中的 knowledge 模块路径列表 + 本次改动 diff</li><li>检测内容：改动是否与 knowledge 描述冲突（字段名/接口签名/常量值/枚举项）</li></ul><blockquote><p>💡 <strong>实现备注</strong>：knowledge-loop skill 不提供独立的 <code>mode=drift-check</code>， 本环节复用 skill 现有「检索模式」中的代码漂移检测能力 + 轻量调用「沉淀模式」仅追加变更历史（不走完整沉淀流程）。</p></blockquote><h3 id="_5-2-漂移处理规则" tabindex="-1">5.2 漂移处理规则 <a class="header-anchor" href="#_5-2-漂移处理规则" aria-label="Permalink to &quot;5.2 漂移处理规则&quot;">​</a></h3><p>&lt;!-- markdownlint-disable MD013 --&gt;</p><table tabindex="0"><thead><tr><th>检测结果</th><th>处理方式</th></tr></thead><tbody><tr><td>无冲突</td><td>仅在命中模块的 <code>_overview.md</code> 末尾「变更历史」追加一行：<code>- {YYYY-MM-DD} [micro-fix] {commit_hash[:8]} {改动摘要}</code></td></tr><tr><td>有冲突（字段/接口/常量被改动）</td><td>追加变更历史 + 调用 knowledge-loop 「检索模式」递增 <code>stability.drift_count</code> + 追加冲突标注：<code>- {YYYY-MM-DD} [micro-fix] {commit_hash[:8]} {改动摘要}：{字段/接口} 已更新</code></td></tr><tr><td>knowledge 模块过期需要重写</td><td>⚠️ 仅追加 <code>⚠️ 本节描述可能与 commit {hash} 后的实际代码不一致，建议下次开发前刷新</code> 提醒，不在 micro-fix 内重写正文（重写需走 standard 沉淀模式）</td></tr><tr><td>&lt;!-- markdownlint-enable MD013 --&gt;</td><td></td></tr></tbody></table><h3 id="_5-3-禁止行为" tabindex="-1">5.3 禁止行为 <a class="header-anchor" href="#_5-3-禁止行为" aria-label="Permalink to &quot;5.3 禁止行为&quot;">​</a></h3><ul><li>❌ 禁止创建新 knowledge 模块（创建模块属于 standard 范畴）</li><li>❌ 禁止改写 <code>_overview.md</code> 正文（仅追加「变更历史」章节）</li><li>❌ 禁止跨模块批量更新（micro-fix 改动应为局部）</li></ul><h3 id="_5-4-完成标记" tabindex="-1">5.4 完成标记 <a class="header-anchor" href="#_5-4-完成标记" aria-label="Permalink to &quot;5.4 完成标记&quot;">​</a></h3><ul><li>0 命中 → <code>knowledge_drift_checked: &quot;no_hits&quot;</code></li><li>有命中无冲突 → <code>knowledge_drift_checked: &quot;appended_history&quot;</code></li><li>有冲突 → <code>knowledge_drift_checked: &quot;drift_recorded&quot;</code></li><li>⚠️ 注意：<code>knowledge_updated</code> 字段保持 <code>false</code> （语义=未沉淀新知识）， 通过新字段 <code>knowledge_drift_checked</code> 区分漂移检测结果</li></ul><h2 id="六、7-j-经验快检-仅-q1-q2-简版" tabindex="-1">六、7-J 经验快检（仅 Q1+Q2 简版） <a class="header-anchor" href="#六、7-j-经验快检-仅-q1-q2-简版" aria-label="Permalink to &quot;六、7-J 经验快检（仅 Q1+Q2 简版）&quot;">​</a></h2><blockquote><p>在 micro-fix 模式下，7-J 从 ❌ 跳过 → ⚡ 简版执行（仅 Q1+Q2，跳 Q3）。 设计依据：micro-fix 改 1 行没纠正没踩坑没新发现时，Q1+Q2 是纯静默退出，零成本；但纠正与踩坑识别能跨任务沉淀 Pattern。</p></blockquote><h3 id="_6-1-执行时机" tabindex="-1">6.1 执行时机 <a class="header-anchor" href="#_6-1-执行时机" aria-label="Permalink to &quot;6.1 执行时机&quot;">​</a></h3><p>环节 H.3 knowledge 漂移检测之后、输出步骤 7 完成标记 JSON 之前。</p><h3 id="_6-2-3-问简版-≤15-秒-静默执行-不输出给用户" tabindex="-1">6.2 3 问简版（≤15 秒，静默执行，不输出给用户） <a class="header-anchor" href="#_6-2-3-问简版-≤15-秒-静默执行-不输出给用户" aria-label="Permalink to &quot;6.2 3 问简版（≤15 秒，静默执行，不输出给用户）&quot;">​</a></h3><p><strong>Q1：本次 micro-fix 中是否有用户纠正？</strong></p><ul><li>判定：用户在阶段 0~7 任一节点说了「不对」/「改错了」/「不是这个文件」/「行号错了」</li><li>命中 → 写入 <code>~/.codebuddy/.learnings/LEARNINGS.md</code>（标注 <code>Source: micro-fix-correction</code>）</li><li>未命中 → 跳过</li></ul><p><strong>Q2：本次是否触发了 LEARNINGS 已记录的坑？</strong></p><ul><li>判定：grep 改动内容是否匹配 LEARNINGS 中已 active 的 <code>Pattern-Key</code></li><li>命中 → 递增对应条目的 <code>Recurrence-Count</code>，更新 <code>Last-Seen</code></li><li><code>Recurrence-Count &gt;= 3 &amp;&amp; Status != promoted</code> → 完成标记追加 <code>experience_alert: {pattern_key}</code></li><li>未命中 → 跳过</li></ul><p><strong>Q3 跳过</strong>：micro-fix 字面修复几乎不会产出新可复用模式，跳过避免噪声。</p><h3 id="_6-3-完成标记字段-沿用现有-schema" tabindex="-1">6.3 完成标记字段（沿用现有 schema） <a class="header-anchor" href="#_6-3-完成标记字段-沿用现有-schema" aria-label="Permalink to &quot;6.3 完成标记字段（沿用现有 schema）&quot;">​</a></h3><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;experience_check&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;clean | recorded_N | alert_pattern_key&quot;</span></span></code></pre></div><ul><li><code>clean</code>：Q1 Q2 全否，零开销退出</li><li><code>recorded_N</code>：新增/更新了 N 条 learnings</li><li><code>alert_pattern_key</code>：某条目 Recurrence-Count &gt;= 3，需关注提升为规则</li></ul><h2 id="七、三道防线-确保「轻量」不变「裸奔」" tabindex="-1">七、三道防线（确保「轻量」不变「裸奔」） <a class="header-anchor" href="#七、三道防线-确保「轻量」不变「裸奔」" aria-label="Permalink to &quot;七、三道防线（确保「轻量」不变「裸奔」）&quot;">​</a></h2><blockquote><p>5 个轻量环节都受这三道防线约束，AI 不得自行扩展或缩减执行边界。</p></blockquote><h3 id="防线-1-硬白名单-执行边界写死" tabindex="-1">防线 1：硬白名单（执行边界写死） <a class="header-anchor" href="#防线-1-硬白名单-执行边界写死" aria-label="Permalink to &quot;防线 1：硬白名单（执行边界写死）&quot;">​</a></h3><ul><li>L1 极简版仅检查红线 §5/6/7/9 共 4 项；禁止 AI 自行扩展到其他红线</li><li>7-A Diff 极简分析的检测项写死在本文件 §3.2 表格内</li><li>7-J 经验快检仅 Q1+Q2，禁止补做 Q3</li></ul><h3 id="防线-2-自动降级触发器" tabindex="-1">防线 2：自动降级触发器 <a class="header-anchor" href="#防线-2-自动降级触发器" aria-label="Permalink to &quot;防线 2：自动降级触发器&quot;">​</a></h3><p>任一极简环节发现「需要更深入处理」→ 立即降级到 standard：</p><table tabindex="0"><thead><tr><th>环节</th><th>触发降级条件</th></tr></thead><tbody><tr><td>5.5a L1</td><td>≥3 个 🔴 / 需决策性思考的 🔴</td></tr><tr><td>7-A Diff</td><td>&gt;3 文件 / &gt;15 行（单文件）/ 不对称修改 / 涉及 lock/配置文件未确认</td></tr><tr><td>7-H.3 knowledge</td><td>仅记录漂移，不降级（漂移处理本身就是 micro-fix 的目标场景）</td></tr></tbody></table><h3 id="防线-3-完成标记-schema-校验" tabindex="-1">防线 3：完成标记 schema 校验 <a class="header-anchor" href="#防线-3-完成标记-schema-校验" aria-label="Permalink to &quot;防线 3：完成标记 schema 校验&quot;">​</a></h3><p>步骤 7 完成标记必须包含以下 micro-fix 专属字段（值不能为 <code>null</code>，缺字段视为未完成）：</p><ul><li><code>diff_stat_checked: true</code>（来自 7-A）</li><li><code>devlog_appended: &quot;round_appended&quot; | &quot;monthly_appended&quot;</code>（来自 7-H.2）</li><li><code>knowledge_drift_checked: &quot;no_hits&quot; | &quot;appended_history&quot; | &quot;drift_recorded&quot;</code> （来自 7-H.3）</li><li><code>experience_check: &quot;clean&quot; | &quot;recorded_N&quot; | &quot;alert_pattern_key&quot;</code>（来自 7-J）</li></ul><blockquote><p>校验由 <code>references/gate-validator.md</code> §「step-id 对照表」中的 <code>7-micro-fix</code> 行执行。</p></blockquote><h2 id="八、向后兼容" tabindex="-1">八、向后兼容 <a class="header-anchor" href="#八、向后兼容" aria-label="Permalink to &quot;八、向后兼容&quot;">​</a></h2><ul><li>旧 micro-fix 完成标记中 <code>experience_check</code> 为 <code>false</code>/省略 → 视为 <code>&quot;clean&quot;</code></li><li>旧 micro-fix 完成标记中 <code>devlog_generated</code>/<code>knowledge_updated</code> 为 <code>false</code> → 不报错（保持原语义）</li><li>新流程从 v2 落地后的第一次 micro-fix 开始生效，不回溯历史</li></ul><h2 id="九、与其他-reference-的关系" tabindex="-1">九、与其他 reference 的关系 <a class="header-anchor" href="#九、与其他-reference-的关系" aria-label="Permalink to &quot;九、与其他 reference 的关系&quot;">​</a></h2><ul><li><code>mode-matrix.md</code> §三bis：声明 micro-fix 触发条件 + 步骤裁剪表（<strong>指向本文件</strong>作为执行细则单一真相源）</li><li><code>steps/step-7-commit.md</code>：环节 A/B/H.2/H.3/J 在 <code>caller=micro-fix-7</code> 时引用本文件</li><li><code>steps/step-router.md</code>：micro-fix 路由表 + 物理检查点白名单</li><li><code>references/gate-validator.md</code>：micro-fix 完成标记的 schema 校验规则</li><li><code>references/output-schemas.md</code>：步骤 7 micro-fix 完成标记 JSON 模板</li></ul><h2 id="维护规则" tabindex="-1">维护规则 <a class="header-anchor" href="#维护规则" aria-label="Permalink to &quot;维护规则&quot;">​</a></h2><p>修改本文件时，必须同步更新：</p><ol><li><code>references/mode-matrix.md</code> §三bis 步骤裁剪表（保持环节状态一致）</li><li><code>steps/step-7-commit.md</code> micro-fix 章节（保持环节状态一致）</li><li><code>references/output-schemas.md</code> 步骤 7 schema（保持字段一致）</li><li><code>references/gate-validator.md</code> <code>7-micro-fix</code> 校验项（保持字段校验一致）</li><li><code>references/_index.md</code> 加载索引（如新增信号字段）</li></ol>`,89)])])}const k=t(a,[["render",l]]);export{p as __pageData,k as default};
